const ALL = WORLD.C.map(([c3, c2, n, ct, area, x, y, lat, lng, d]) => ({ c3, c2, n, ct, area, x, y, lat, lng, d })), BY = {}; ALL.forEach(c => { BY[c.c3] = c; });
const AREA = ALL.reduce((a, c) => a + c.area, 0);
