const pf = x => x > 0 && x < 10 ? x.toFixed(1).replace('.', ',') : String(Math.round(x));
const ST = ['Visitei', 'Morei', 'Quero ir'], RANK = { Morei: 3, Visitei: 2, 'Quero ir': 1 }; let M_XP = null;
